import{_ as o,a8 as a,o as n,c as i,ah as s,aV as d,K as e}from"./chunks/framework.BNwxUeRp.js";import"./chunks/theme.BC7t94LL.js";const G=JSON.parse('{"title":"RAG 概述","description":"","frontmatter":{"title":"RAG 概述","abstract":"RAG 检索增强生成概述，讲解大模型幻觉与知识时效性两大缺陷的背景、RAG 工作原理、典型项目流程与核心工具依赖。","created":"2026-07-08T00:00:00.000Z","tags":["AI","RAG","检索增强生成"],"type":"概念解释","related":["[[AI 应用核心范式-MOC]]"],"reference":"","category":["🔍 RAG"]},"headers":[],"relativePath":"vault/Knowledge/AI/RAG 概述.md","filePath":"vault/Knowledge/AI/RAG 概述.md","lastUpdated":1790655645000}'),h={name:"vault/Knowledge/AI/RAG 概述.md"};function g(c,t,p,_,m,u){const r=a("NolebaseGitContributors"),l=a("NolebaseGitChangelog");return n(),i("div",null,[t[0]||(t[0]=s('<h1 id="rag-概述" tabindex="-1">RAG 概述 <a class="header-anchor" href="#rag-概述" aria-label="Permalink to “RAG 概述”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>大模型（如 ChatGPT）存在两个固有缺陷：<strong>幻觉</strong>（生成不实信息）和<strong>知识时效性</strong>（训练数据截止时间限制）。对于企业私有知识，模型更无法直接访问。</p><p>解决方案有两种：</p><ol><li><strong>垂直领域微调</strong>：融合企业私有知识重新训练</li><li><strong>RAG（检索增强生成）</strong>：通过检索外部知识库，将相关文档注入 prompt，减少幻觉，提高准确性和时效性</li></ol><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to “原理”">​</a></h2><p>RAG 在生成回答前，先从外部知识库中检索与用户问题相关的文档片段，将其与问题拼接后送入大模型生成答案。核心思路：<strong>让 LLM 先&quot;查资料&quot;再回答</strong>。</p><h2 id="典型项目流程-以-java-学科在线答疑系统为例" tabindex="-1">典型项目流程（以 Java 学科在线答疑系统为例） <a class="header-anchor" href="#典型项目流程-以-java-学科在线答疑系统为例" aria-label="Permalink to “典型项目流程（以 Java 学科在线答疑系统为例）”">​</a></h2><ol><li><strong>QA 数据入库</strong>：将历史 QA 数据集存入 MySQL</li><li><strong>MySQL 快速匹配</strong>：用户 query 与历史问题做相似度计算 <ul><li>相似度 ≥ 0.85 → 直接返回已有答案</li><li>相似度 &lt; 0.85 → 进入 RAG 系统检索</li></ul></li><li><strong>本地知识库搭建</strong>： <ul><li>加载本地文档</li><li>文档切分（分割为 chunks）</li><li>向量化（Embedding）</li><li>存入向量数据库（Milvus）</li></ul></li><li><strong>Milvus 检索</strong>：query 向量化后检索 top-k 相似文本段</li><li><strong>生成答案</strong>：query + 检索文本段拼接，送入 LLM 生成最终结果</li></ol><p><img src="'+d+'"></p><h2 id="核心工具" tabindex="-1">核心工具 <a class="header-anchor" href="#核心工具" aria-label="Permalink to “核心工具”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>作用</th></tr></thead><tbody><tr><td><strong>Ollama</strong></td><td>开源大模型服务工具，支持本地运行大模型</td></tr><tr><td><strong>LangChain</strong></td><td>LLM 通用接口框架，链接各组件，简化应用开发</td></tr><tr><td><strong>Milvus</strong></td><td>开源向量数据库，存储和检索嵌入向量</td></tr></tbody></table><h2 id="环境依赖" tabindex="-1">环境依赖 <a class="header-anchor" href="#环境依赖" aria-label="Permalink to “环境依赖”">​</a></h2><ul><li>Python ≥ 3.10</li><li><code>pip install faiss-cpu langchain qianfan</code><em>（内容由AI生成，仅供参考）</em></li></ul>',14)),e(r),e(l)])}const f=o(h,[["render",g]]);export{G as __pageData,f as default};
